      running:true,speed:1,autoInvite:true,autoAdvance:true,pauseAfterBattle:false,battle:null,logs:[],
      stats:{battles:0,wins:0,recruited:0,steps:0,silverEarned:0,playSeconds:0,bosses:0,expEarned:0,defeats:0},
