/* The guild tools used on the relay road determine silhouette and color. */
(function(root){
  'use strict';
  const guilds=[
    ['铜鸣环','sound','gold'],['分节撑杆','spear','steel'],['卷尺竹针','projectile','jade'],
    ['护索双钩','thread','steel'],['窑钩','blade','fire'],['石槌','impact','gold'],
    ['药雾喷筒','healing','jade'],['拨轮机弩','projectile','steel'],['火铲陶盾','guard','fire'],
    ['翻土耙','spear','gold'],['堰板木锤','guard','steel'],['更板','sound','gold'],
    ['宽刃刨','blade','steel'],['短桨风带','element','ice'],['探索钩','thread','steel'],
    ['铜摆沙漏','arcane','gold'],['竹焙笼','healing','jade'],['解栅斧','blade','fire'],
    ['哨弓','projectile','gold'],['测绘尺','qi','ice'],['竹梭织带','thread','jade']
  ];
  const rows=[];
  for(const [i,[tool,category,palette]] of guilds.entries()){
    for(const [phase,verb] of [['attack','出手'],['heal','援护'],['guard','固守']]){
      const id='relay-'+(i+1)+'-'+phase;
      const range=phase==='attack'?(i%3===1?'melee':'ranged'):'self';
      const anchor=phase==='attack'?(range==='ranged'?'flight':'target'):'beneficiary';
      rows.push([id,tool+' · '+verb,phase==='heal'?'healing':phase==='guard'?'guard':category,'school/'+id,palette,range,'沿'+tool+'的形制绘制'+verb+'动作。',anchor]);
    }
  }
  root.JXSectFxA=Object.freeze({rows,guilds});
})(globalThis);


;
