/* Encounter choreography uses the implement drawn on the current master sheet. */
(function(root){
  'use strict';
  const variants={normal:'出招',area:'横扫',heavy:'重击','area-heavy':'范围重击'};
  const profiles={
    pole:['收费钩杖','spear','steel'],wheel:['舵轮','impact','gold'],cane:['支撑杖','spear','steel'],
    lamp:['夹层灯','element','fire'],key:['闸钥','blade','gold'],fist:['缠布拳','impact','steel'],
    gate:['栏门闸钩','spear','steel'],tongs:['窑钳','element','fire'],bow:['短弓飞箭','projectile','ice','ranged'],
    mallets:['双槌','impact','gold'],plumb:['水尺垂锤','thread','steel'],flag:['折篷旗','thread','fire'],
    yoke:['担绳滑轮','thread','gold'],ballast:['绳系压舟石','impact','steel'],hoop:['草编驯圈','thread','jade'],
    token:['传信牌','projectile','gold','ranged'],hook:['系船钩','spear','steel'],bell:['盗铃钩','sound','gold'],
    poker:['拨火棍与盾','guard','fire'],scale:['杆秤砝码','impact','gold'],fork:['三齿船叉','spear','ice'],
    winch:['探井绞盘','thread','steel'],valve:['蝶阀扳手','blade','gold'],paddle:['短桨','spear','gold'],
    blade:['短弯刀','blade','steel'],net:['抄网','thread','jade'],cleaver:['宽刃短刀','blade','steel'],
    claw:['山犬扑咬','spirit','jade'],sand:['翻秤扬砂','element','gold'],contact:['近身冲撞','impact','steel']
  };
  const masterRoles={
    '断桥夺路人':'pole','铁篷舵手':'wheel','瘸脚镖客':'cane','走私船主':'lamp','枯渠守望':'key',
    '泥巷拳师':'fist','斜门守卫':'gate','夜行窑匠':'tongs','黑砾猎手':'bow','双槌行者':'mallets',
    '水尺看守':'plumb','沉篷领队':'flag','暗井挑夫':'yoke','沉石舵主':'ballast','草圈驯手':'hoop',
    '栈桥密探':'token','岸边强梁':'hook','盗铃快手':'bell','废炉铁卫':'poker','藏秤掌柜':'scale',
    '水匪蒲三':'fork','枯井巡工':'winch','阀箱看手':'valve'
  };
  const guardArt=['paddle','bow','wheel','blade','net','cleaver','hook','claw'];
  const heroes=new Map(root.JXData.HEROES.map(h=>[h.id,h]));
  const namedHeroes=new Map(root.JXData.HEROES.map(h=>[h.name,h]));
  for(const sect of root.JXData.SECTS)profiles[sect.id]=[sect.weapon,'impact','steel'];
  const rows=[];
  for(const [key,[name,category,palette,range='melee']] of Object.entries(profiles)){
    for(const [variant,action] of Object.entries(variants)){
      const flight=range==='ranged'&&!variant.includes('area');
      rows.push(['road-'+key+'-'+variant,name+' · '+action,category,'boss/'+key+'-'+variant,palette,range,
        name+'按'+action+'的实际结算时机演出。',flight?'flight':'target']);
    }
  }
  function identify(actor,event){
    const name=String(actor.name||'').trim(),art=root.JXBossArt?.get(name);
    if(actor.dungeonId==='five_journey06'&&name==='藏秤掌柜·时停舟'&&event.area&&
        (event.control==='stun'||event.skillName==='翻秤扬砂'))
      return ['sand','encounter-action','combat-rules.js 的翻秤扬砂结算'];
    if(Number.isInteger(actor.enemyArt)&&guardArt[actor.enemyArt])
      return [guardArt[actor.enemyArt],'guard-art','巡路母版格位 '+actor.enemyArt];
    const shared=heroes.get(art?.heroId)||heroes.get(actor.artId)||heroes.get(actor.id)||namedHeroes.get(name);
    if(shared)return [shared.id==='instance_a88'?'paddle':shared.sect,'character-art',shared.name+'的随身器具'];
    const role=(art?.canonicalName||name).split('·')[0].trim();
    if(masterRoles[role])return [masterRoles[role],'portrait-design',role+'的母版器具设定'];
    if(name==='炭炉·应锤偶'||name==='汛炉·合闸偶')return ['mallets','encounter-design','锻造工序使用的试锤偶'];
    const inferred=[[/兽|犬|獾|狼/,'claw'],[/弩|箭|短弓/,'bow'],[/窑|巡火|炭/,'tongs'],
      [/水车|机轮|机关/,'wheel'],[/短刀|快手/,'blade'],[/船桨|撑杆/,'paddle'],[/绞盘|绳/,'winch'],[/槌|锤/,'mallets']];
    for(const [pattern,key] of inferred)if(pattern.test(name))return [key,'name-inference','据遭遇名称推断动作'];
    return ['contact','neutral','无器具设定的遭遇使用近身接触提示'];
  }
  function lookup(actor,variant,event={}){
    if(!actor||!variants[variant])return null;
    const [implement,basis,source]=identify(actor,event);
    return {id:'road-'+implement+'-'+variant,implement,basis,mode:basis,source,
      reason:source+'；'+profiles[implement][0]+'在'+variants[variant]+'结算时播放。'};
  }
  root.JXBossFx=Object.freeze({rows,lookup,choose:(actor,variant,event)=>lookup(actor,variant,event)?.id||null,reason:(actor,variant,event)=>lookup(actor,variant,event)?.reason||''});
})(globalThis);

