        const condition=hp<=0?'阵亡':hp<=max*.2?'残血':hp<max?'受伤':'完好';
        row.dataset.condition=condition;
        row.dataset.uid=actor.uid;
        row.className='party-health-card';
        row.title=actor.name+' · '+condition+' · '+hp+' / '+max;
        portrait.className='party-health-portrait';
