      hud.hidden=!snapshot;
      if(!snapshot)return;
      const enemy=snapshot.enemy,{total,defeated}=snapshot.opposition||{total:1,defeated:0};
      const down=Math.min(total,defeated+(enemy.hp<=0?1:0));
      const key=[snapshot.battleId,enemy.name,total,down].join('|');
      if(hud.dataset.roster===key)return;
