    const screen=document.querySelector('#page');
    const tabs=[...screen.querySelectorAll(':is(.tabs,.card-tabs,.shop-tabs,.growth-tabs,.growth-role-tabs,.growth-color-tabs) [data-action].active')]
      .map(el=>el.dataset.action+'='+el.dataset.id).join('/');
