      const info=engine.expPillInfo(s,hero), need=engine.nextLevelXp(hero), full=hero.level>=info.cap;
      panel.querySelector('.pill-xp-label b').textContent='Lv.'+hero.level;
      panel.querySelector('.pill-xp-label small').textContent=full?'本章等级已满':'经验 '+Math.floor(hero.xp).toLocaleString()+' / '+need.toLocaleString();
      panel.querySelector('.bar.xp').dataset.pillCapped=String(full);
