        '<div class="ac-rail">' + icon('ore') + '<progress max="1" value="' + ratio + '" aria-label="挖宝进度"></progress>' + icon('flag') + '<b>第' + number(floor) + '层</b></div>' +
        '<div class="ac-expedition-controls"><div class="ac-tiny-team">' + avatars + '</div><span>' + esc(message) + (!x.empty && !x.ready && !x.opening ? '<small>预计 ' + time(x.remaining || 0) + '</small>' : '') + '</span>' + control + '</div>' +
        '<div class="ac-bag"><small>背包</small>' + (bag || '<span>暂无宝物</span>') + '</div></article>';
