          body = '<div class="ac-actor-detail">' + actorArt(actor) + facts([['等级', actor.level], ['职责', {tank:'承伤',healer:'治疗',dps:'输出'}[actor.role] || '输出'], ['气血上限', number(actor.maxHp)]]) + '</div>';
