      const tiles=list.map(h=>{
        const m=meta(h.id),slot=slots.get(h.uid),name=nameOf(s,h);
        const label=(h.uid===s.playerUid?'主角 · ':'')+name;
        const state=slot?'研习中':available?'传功 · '+t.trainingCost.silver+' 银两':'席位已满';
        return '<button type="button" class="pc-collection-cell training-cell rarity-'+m.rarity+(slot?' in-seat':'')+'" data-action="train-select" data-id="'+esc(h.uid)+'" data-drag-key="'+esc(h.uid)+'" data-drag-group="pool"'+(slot?' data-studying':'')+' aria-label="'+esc(label+'，'+state)+'" title="'+esc(label+' · '+state)+'">'+
          '<span class="pc-cell-art">'+portrait(m)+'</span><span class="pc-cell-caption"><strong>'+esc(label)+'</strong><small>Lv.'+h.level+'</small></span>'+(slot?'<span class="training-rank">'+state+'</span>':'')+'</button>';
      });
