        return '<div class="training-bed filled invitation">'+itemArt('invite')+'<div class="training-bed-meta"><strong>江湖邀约</strong><span>'+(slot.ready?'来客已至':'飞帖传书')+'</span>'+gauge(slot)+
          '<button class="training-claim" data-action="claim-invite" data-id="'+i+'" '+(slot.ready?'':'disabled')+'>'+(slot.ready?'迎接侠客':c.duration(slot.remaining))+'</button></div></div>';
