  function resetFrameClock(){lastFrame=performance.now();lastFrameWall=Date.now();}
  const ui={page:'adventure',filter:'all',query:'',region:'all',sort:'rarity',starter:null,starterPage:0,heroModal:null,ready:false,viewTime:0,tab:'heroes'};
