  state=state||E.createState();S.init(state);
  let combat=null;
  function ensureCombat(){return combat||(combat=JXCombat.create({
    state:()=>state,onImpact:e=>sound(e.critical?'critical':'hit'),
    onGuardDefeat:()=>sound('defeat'),onGuardRecover:()=>sound('recover')
  }));}
  const isGuardDefeat=e=>e.type==='defeat'&&e.closingGuard===true;
  function receiveCombatEvents(events){combat.receive(events);const finished=events.find(e=>e.type==='challenge-complete'&&e.result?.kind!=='endgame');if(finished)ui.pendingReport=finished.result;}
  function save(show=false,settledAt=Date.now()){if(!entered||!ui.ready||accountUI?.active())return true;try{state.lastSaved=settledAt;localStorage.setItem(KEY,E.serialize(state));if(show)toast('江湖进度已保存。');return true;}catch(e){toast('本地存储不可用，请在设置中导出存档。');return false;}}
  function toast(message){if(handbook?.notify(message))return;const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
  function sound(kind='click'){
    if(kind==='click'||!state.settings.sound)return;
    try{
      audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();
      if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});
      const now=audioCtx.currentTime,notes=kind==='defeat'?[330,262,196]:kind==='recover'?[392,494,587]:null;
      const tones=notes||[kind==='reward'?660:kind==='critical'?280:kind==='hit'?160:440];
      tones.forEach((pitch,i)=>{
        const o=audioCtx.createOscillator(),g=audioCtx.createGain(),start=now+i*.11;
        o.type=kind==='hit'?'square':'triangle';o.frequency.setValueAtTime(pitch,start);
        if(!notes)o.frequency.exponentialRampToValueAtTime(kind==='reward'?880:kind==='hit'||kind==='critical'?65:330,start+.12);
        g.gain.setValueAtTime(.025,start);g.gain.exponentialRampToValueAtTime(.001,start+.18);
        o.connect(g);g.connect(audioCtx.destination);o.start(start);o.stop(start+.2);
      });
    }catch{}
  }
  function openModal(html,cls=''){
    const m=$('#modal'),sameHero=m.open&&ui.heroModal&&m.querySelector('.modal-head h2')?.textContent===meta(ui.heroModal)?.name;
    const scrolls=sameHero?JXScroll.capture(m):null;
    m.className=cls;
    globalThis.JXSafeDOM.replace(m,html);
    JXReferenceUI.clean(m);
    if(!m.open)m.showModal();
    if(scrolls)JXScroll.restore(m,scrolls);else m.scrollTop=0;
  }
  function closeModal(){if(!ui.ready)return;$('#modal').close();ui.heroModal=null;}
  const modalHeader = title => '<div class="modal-head"><h2>'+esc(title)+'</h2><button class="icon-button" data-action="close" aria-label="关闭">'+icon('close')+'</button></div>';
  const navigation=[
    ['adventure','sword','历练'],
    ['map','map','地图路线'],
    ['team','people','侠客',[['team','people','侠客卡册'],['training','leaf','传功邀约'],['cosmetics','star','角色外观'],['martial','book','主角武学'],['equipment','hammer','主角装备'],['inventory','bag','背包'],['forge','star','神兵铸造'],['craft','hammer','百工坊']]],
    ['dex','book','图鉴'],
    ['activities','gift','活动',[['activities','gift','白芦行装'],['weekly','clock','本周目标'],['challenges','tower','秘境挑战'],['activity-dungeon','people','每日护路'],['dungeons','map','历代秘境']]],
    ['social','heart','社交',[['social','people','好友世界'],['card-trade','bag','同道集换'],['activity-support','heart','亲友助战']]],
    ['shop','bag','商店',[['shop','bag','江湖商店'],['brocade-shop','jade','驿券商店']]],['achievements','trophy','成就']
  ];
  const navPhone=matchMedia('(max-width: 640px)'), navStore='jianghu-navigation-open-v1';
  try {JXWorldMigration.movePreference(localStorage,navStore,'1jkzp6m.cpvd3k');}catch{}
  let navExpanded={}, navSheet='', lastNavPage='';
