    document.body.classList.remove('at-entry');
    lastNavPage='';navSheet='';
    const chapter='<button id="chapter-card" class="chapter-card journey-home" data-action="nav" data-id="adventure" aria-label="返回正在战斗的历练首页"><span class="chapter-scenery route-thumb" aria-hidden="true"></span><span class="chapter-card-copy"><small></small><strong></strong></span><span class="bar"><span></span></span><span class="chapter-bottom"><span></span><span></span></span></button>';
    const footer='<div class="sidebar-bottom"><button class="nav-item" data-action="nav" data-id="guide">'+icon('help')+'游玩指南</button><button class="nav-item" data-action="nav" data-id="settings">'+icon('gear')+'设置与存档</button></div>';
    globalThis.JXSafeDOM.replace($('#app'),JXAppearance.cast()+'<aside class="sidebar" id="sidebar"><div class="nav-dismiss" data-action="nav-dismiss" aria-hidden="true"></div><nav class="nav-scroll gui-nav-primary" aria-label="主导航">'+chapter+'<div id="sidebar-pages">'+sidebarPages()+'</div></nav>'+footer+'</aside><div class="workspace"><header class="topbar" id="topbar"></header><a class="skip-main" href="#page">跳到主要内容</a><main class="page" id="page" tabindex="-1"></main></div>');
    render();
