    const controls='<div class="scene-controls"><span class="auto-status"><span class="status-dot"></span>'+(state.running?'自动历练中':'历练已暂停')+'</span><label class="toggle-label"><input type="checkbox" data-change="auto" '+(state.autoInvite?'checked':'')+'>自动结交</label>'+btn('整备','nav','equipment','small')+btn(icon(state.running?'pause':'play')+(state.running?'暂停':'继续'),'running','','primary small')+'</div><div class="battle-footer"><span>结交帖 '+state.inventory.invite+'　 ·　累计胜场 '+fmt(state.stats.wins)+'</span><span>离线自动历练 · 最多 8 小时</span></div>';
