    const playerCard='<section class="panel gui-player-card"><div class="panel-header"><h3>我的主角</h3>'+btn('详情','hero',player.uid,'small quiet')+'</div><div class="panel-body"><div class="flex">'+portrait(playerMeta)+'<div><strong>'+esc(playerMeta.name)+'</strong><p class="panel-note">Lv.'+player.level+' · '+esc(JXMartial.heartMethodFor(player)?.name||({tank:'承伤',healer:'治疗',dps:'输出'}[E.getRole(player)]))+'</p></div></div><p class="panel-note">装备 '+Object.keys(player.equipment||{}).length+' / 12</p>'+btn('查看养成','nav','equipment','wide')+'</div></section>';
