    const log='<div class="log-list full-log">'+state.logs.slice(0,10).map(l=>'<div class="log-row '+esc(l.type)+'"><time>'+hm(l.time)+'</time><span>'+esc(JXCombatRules.formatAssistLog(l.message))+'</span></div>').join('')+'</div>';
