  function statStrip(items){return '<div class="stat-strip">'+items.map(([label,val,unit],i)=>'<div class="stat-box"><span>'+icon(['people','flag','sword','heart'][i]||'star')+label+'</span><strong>'+fmt(val)+'<small>'+unit+'</small></strong></div>').join('')+'</div>';}
  function team(){let heroes=state.heroes.filter(h=>(ui.filter==='all'||affiliationFilter(meta(h.id))===ui.filter)&&(!ui.query||meta(h.id).name.includes(ui.query)));heroes.sort((a,b)=>ui.sort==='level'?b.level-a.level:meta(b.id).rarity-meta(a.id).rarity);return statStrip([['已结交',state.heroes.length,'位侠客'],['上阵',state.team.length,'/ 5'],['队伍战力',E.teamPower(state),''],['累计结缘',state.stats.recruited,'次']])+panel('当前阵容',btn('按弱点一键上阵','auto-lineup','','small primary')+X.roleSummary()+'<div class="party">'+Array.from({length:5},(_,i)=>state.team[i]?heroCard(owned(state.team[i])):'<button class="hero-card empty" data-action="collection-focus">'+icon('plus')+'<span>待君结缘</span></button>').join('')+'</div><div class="preset-row"><span class="tiny muted">阵容方案</span>'+Array.from({length:5},(_,i)=>'<div class="preset-group"><button data-action="load-preset" data-id="'+i+'">'+(i+1)+' · '+(state.presets[i]?.length||0)+'人</button><button data-action="save-preset" data-id="'+i+'" title="保存至方案'+(i+1)+'">'+icon('save')+'</button></div>').join('')+'</div>',btn(state.battle?'本场结束后暂停':state.running?'暂停历练':'继续历练',state.battle||state.running?'formation':'running','','small'))+'<div class="toolbar" style="margin-top:24px"><input class="search" id="hero-search" value="'+esc(ui.query)+'" placeholder="搜索侠客姓名" aria-label="搜索侠客"><select class="select" data-change="filter"><option value="all">全部归属</option>'+affiliationOptions().map(([id,label])=>'<option value="'+esc(id)+'" '+(ui.filter===id?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select><select class="select" data-change="sort"><option value="rarity" '+(ui.sort==='rarity'?'selected':'')+'>品质优先</option><option value="level" '+(ui.sort==='level'?'selected':'')+'>等级优先</option></select></div><div class="hero-grid" id="hero-grid">'+(heroes.map(h=>heroCard(h,true)).join('')||'<div class="empty-note">尚未结交此归属侠客，前往地图寻访吧。</div>')+'</div>';}
  function dexView(){return KUI.dex(ui,CUI);}
  const trainingHouse=JXTrainingUI.create({getState:()=>state,esc,meta,portrait,affiliationFilter,affiliationOptions,duration,hm,fmt,itemName,icon,btn,openModal,modalHeader,toast});
  function trainingView(){return trainingHouse.view();}
  const activityDetails={'activity-dungeon':'dungeon','activity-world':'world','activity-underground':'underground','activity-tower':'tower'};
  JXDrag.bind({
    source(node){
      if(!node.closest('[data-drag-scope="training"]')||node.closest('[data-train-seat] button'))return null;
      const element=node.closest('[data-drag-key]');
      if(!element||element.hasAttribute('data-studying'))return null;
      return {element,uid:element.dataset.dragKey,group:element.dataset.dragGroup,seat:Number(element.dataset.trainSeat)};
    },
    target(node,source){
      const slots=S.training(state).slots;
      if(node.closest('[data-train-pool]')&&source.group==='seat'){
        const pool=node.closest('[data-train-pool]');
        const element=pool.querySelector('[data-drag-key="'+CSS.escape(source.uid)+'"]')||pool;
        return {element,allowed:slots[source.seat]?.uid===source.uid,action:'stop-training',seat:source.seat};
      }
      const element=node.closest('[data-train-seat]');
      if(!element)return null;
      const seat=Number(element.dataset.trainSeat),other=slots[seat]?.uid||'';
      if(source.group==='seat')return {element,seat,other,action:'move-training',allowed:slots[source.seat]?.uid===source.uid&&source.seat!==seat};
      return {element,seat,action:'train',allowed:!other&&!slots.some(s=>s?.uid===source.uid)};
    },
    async commit(source,target){
      const {action,seat,other}=target;
      if(accountUI.active()){
        const args={id:String(seat),uid:source.uid};
        if(action==='move-training')args.value=other;
        const result=await accountUI.command(action,args,source.element);
        return {ok:!!result?.ok,apply:render};
      }
      const result=action==='train'?S.startTraining(state,source.uid,seat):action==='stop-training'?
        S.stopTraining(state,seat,source.uid):S.moveTraining(state,source.uid,seat,other);
      return {ok:result.ok,apply(){if(result.ok){save();sound('reward');}toast(result.message);render();}};
    }
  });
