  function startJourney() {
    const dialog=$('#modal'), chosen=D.SECTS.find(s=>s.id===ui.starter);
    if(ui.ready||!chosen||!dialog.open||dialog.dataset.phase!=='choosing')return;
    const next=E.createState($('#player-name').value,chosen.id);
    S.init(next);
    try {
      next.lastSaved=Date.now();
      localStorage.setItem(KEY,E.serialize(next));
    } catch {
      dialog.querySelector('.starter-caption').textContent='本机存档写入失败，请检查可用空间后重试。';
      return;
    }
    state=next;fresh=false;
    JXStarterUI.reveal(dialog,chosen,()=>{
      if(!entered||state!==next||!dialog.open||dialog.dataset.phase!=='revealing')return;
      delete dialog.dataset.phase;
      dialog.close();ui.ready=true;tutorialNew=true;resetFrameClock();render();
    });
  }
  function report(title,result){
    if(result.kind==='forge'&&result.workshop){
      ui.forgeRecipe=result.id;ui.forgeRecipePage=undefined;ui.page='forge';render();
      JXWorkshopShowcase.show(result.workshop);
      return;
    }
    globalThis.JXInteractionFeedback?.result('report',result);
    const lines=result.log||[result.message];
    const bosses=(result.bosses||[]).map(b=>'<article>'+(globalThis.JXBossArt?.sprite(b.name)||'')+'<small>'+esc(b.name)+'</small><small>'+(b.won?'已击败':'未击败')+' · '+b.rounds+'回合</small></article>').join('');
    const loot=(result.loot||[]).map((item,index)=>{
      const message=esc(typeof item==='string'?item:item.name||item.message||''),detail=result.lootDetails?.[index];
      return '<li>'+(detail?.key?'<button type="button" class="tip-name-button" aria-haspopup="dialog" data-action="item-tip" data-id="'+esc(detail.key)+'"'+(detail.item?' data-tip-snapshot="'+esc(JSON.stringify(detail.item))+'"':'')+'>'+message+'</button>':message)+'</li>';
    }).join('');
    const back=result.kind==='forge'?btn('返回神兵铸造','forge-return',result.id,'primary'):result.kind==='event'&&Object.values(activityDetails).includes(result.id)?btn('返回活动','activity-return',result.id,'primary'):result.kind==='dungeon'?btn('返回历代秘境','activity-return','dungeons','primary'):'';
    openModal(modalHeader(title)+'<div class="modal-body"><h3 class="report-title">'+(result.won===true?'挑战告捷':result.won===false?'再接再厉':'江湖有获')+'</h3><p class="text-center">'+esc(result.message)+'</p><div class="reward-line" style="justify-content:center;margin-top:15px">'+rewardText(result.rewards||result.reward)+'</div>'+(loot?'<ul class="report-loot" aria-label="实际掉落">'+loot+'</ul>':'')+'<div class="report-bosses">'+bosses+'</div><details class="report-history"><summary>战斗记录</summary><div class="report-log">'+lines.map(x=>'<div>'+esc(JXCombatRules.formatAssistLog(typeof x==='string'?x:x.message||JSON.stringify(x)))+'</div>').join('')+'</div></details></div><div class="modal-footer">'+back+btn(back?'查看历练':'收好行囊，继续出发','close','',back?'':'primary')+'</div>');
  }
